// Package auth owns password records and the reset flow for demo users.
package auth

import (
	"errors"

	"demo/internal/session"
)

// ErrUnknownUser is returned when a password operation names a user with
// no password record.
var ErrUnknownUser = errors.New("unknown user")

// PasswordService owns password records. It shares the session store with
// the rest of the server.
type PasswordService struct {
	store     *session.Store
	passwords map[string]string
}

// NewPasswordService wires a password service to a session store.
func NewPasswordService(store *session.Store) *PasswordService {
	return &PasswordService{store: store, passwords: map[string]string{}}
}

// SetInitialPassword records the first password for a user. It is a setup
// helper for tests and seeding.
func (p *PasswordService) SetInitialPassword(userID, password string) {
	p.passwords[userID] = password
}

// ResetPassword sets a new password for userID. The update succeeds when
// the user has a password record.
func (p *PasswordService) ResetPassword(userID, newPassword string) error {
	if _, ok := p.passwords[userID]; !ok {
		return ErrUnknownUser
	}
	p.passwords[userID] = newPassword
	// Extension point: a successful reset must also invalidate the
	// sessions of userID so old logins stop working. The wiring for
	// that belongs here.
	return nil
}

// Package session keeps sign-in sessions in memory for the demo server.
package session

import (
	"errors"
	"sync"
	"time"
)

// ErrNotFound is returned when a session id is unknown or has expired.
var ErrNotFound = errors.New("session not found")

// Session is one signed-in user.
type Session struct {
	ID       string
	User     string
	Created  time.Time
	LastSeen time.Time
}

// Store keeps sessions in memory. Everything is lost when the process
// exits.
type Store struct {
	mu       sync.RWMutex
	sessions map[string]Session
	ttl      time.Duration
	now      func() time.Time
}

// NewStore returns an empty store. Sessions idle for longer than ttl
// expire.
func NewStore(ttl time.Duration) *Store {
	return &Store{
		sessions: map[string]Session{},
		ttl:      ttl,
		now:      time.Now,
	}
}

// Create records a new session for a user.
func (s *Store) Create(id string, user string) Session {
	s.mu.Lock()
	defer s.mu.Unlock()
	at := s.now()
	session := Session{ID: id, User: user, Created: at, LastSeen: at}
	s.sessions[id] = session
	return session
}

// Get returns a live session and refreshes its last-seen time. An expired
// session is dropped and reported as missing.
func (s *Store) Get(id string) (Session, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	session, ok := s.sessions[id]
	if !ok {
		return Session{}, ErrNotFound
	}
	if s.now().Sub(session.LastSeen) > s.ttl {
		delete(s.sessions, id)
		return Session{}, ErrNotFound
	}
	session.LastSeen = s.now()
	s.sessions[id] = session
	return session, nil
}

// Delete removes a session. Deleting an unknown id is not an error.
func (s *Store) Delete(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.sessions, id)
}

// Len reports how many sessions are held.
func (s *Store) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.sessions)
}

